 "content": "def transform(grid):
    g=[row[:] for row in grid]
    # Marker colors are listed in their visible row-major pattern order; the
    # three 8-valued silhouette bands use that same order top-to-bottom.
    colors=[]
    for row in g:
        for v in row:
            if v not in (0,8) and v not in colors:
                colors.append(v)
    # Bands are contiguous horizontal runs of 8-cells, grouped by their
    # distinct vertical levels in the silhouette.
    rows=[r for r,row in enumerate(g) if 8 in row]
    if not rows or not colors:
        return g
    bands=[]
    for r in rows:
        if not bands or r>bands[-1][-1]+1:
            bands.append([r])
        else:
            bands[-1].append(r)
    # Use each horizontal stripe family (top, center, bottom) as the mapping.
    # Where adjacent shapes touch, column pattern identifies the next band.
    if len(bands)==1:
        # Split at changes in occupied columns, which distinguish adjoining pieces.
        bands=[]
        for r in rows:
            cols=[c for c,v in enumerate(g[r]) if v==8]
            if not bands or cols!=[c for c,v in enumerate(g[bands[-1][-1]]) if v==8]:
                bands.append([r])
            else: bands[-1].append(r)
    for i,rset in enumerate(bands):
        color=colors[min(i,len(colors)-1)]
        for r in rset:
            for c,v in enumerate(g[r]):
                if v==8:g[r][c]=color
    return g
